<?php $id = (int)$z['id']; $locked = $z['has_attempts']; ?>
<div class="d-flex flex-wrap gap-2 align-items-center mb-3"><h2 class="h5 mb-0"><?= e($z['title']) ?></h2><span class="badge text-bg-<?= $z['is_published'] ? 'success' : 'secondary' ?>"><?= $z['is_published'] ? 'منشور' : 'مسودة' ?></span><span class="text-muted"><?= e($z['ss']['subject_name'] . ' — ' . $z['ss']['grade_name'] . ' / ' . $z['ss']['section_name']) ?></span>
  <span class="ms-auto d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= url('school/lms?ss=' . (int)$z['section_subject_id']) ?>">رجوع</a>
  <?php if (!$z['is_published']): ?><button class="btn btn-success" data-api="<?= url("api/v1/school/lms/quizzes/$id/publish") ?>" data-body='{"publish":true}' data-confirm="نشر الاختبار للطلاب؟">نشر</button><?php elseif (!$locked): ?><button class="btn btn-outline-warning" data-api="<?= url("api/v1/school/lms/quizzes/$id/publish") ?>" data-body='{"publish":false}'>إلغاء النشر</button><?php endif; ?>
  <?php if (!$locked): ?><button class="btn btn-outline-danger" data-api="<?= url("api/v1/school/lms/quizzes/$id") ?>" data-method="DELETE" data-confirm="حذف الاختبار؟">حذف</button><?php endif; ?></span></div>
<div class="card-s mb-3 small d-flex flex-wrap gap-3"><span>الأسئلة: <strong><?= count($z['questions']) ?></strong></span><span>المجموع: <strong><?= (float)$z['total_points'] ?></strong></span><span>المدة: <strong><?= $z['duration_min'] ? (int)$z['duration_min'] . ' د' : 'مفتوحة' ?></strong></span><span>المحاولات: <strong><?= (int)$z['max_attempts'] ?></strong></span><span>الخلط: <strong><?= $z['shuffle_questions'] ? 'نعم' : 'لا' ?></strong></span><?php if ($z['opens_at']): ?><span dir="ltr">يفتح <?= e($z['opens_at']) ?></span><?php endif; ?><?php if ($z['closes_at']): ?><span dir="ltr">يُغلق <?= e($z['closes_at']) ?></span><?php endif; ?></div>
<?php if ($locked): ?><div class="alert alert-info">بدأ طلاب حل الاختبار؛ أسئلته مقفلة.</div><?php endif; ?>
<div class="row g-3"><div class="col-lg-6"><div class="card-s"><h3 class="h6">أسئلة الاختبار</h3><?php if (!$z['questions']): ?><div class="empty-state">أضف أسئلة من البنك.</div><?php endif; ?><?php foreach ($z['questions'] as $i => $q): ?><div class="border-bottom py-2 d-flex gap-2"><span><?= $i + 1 ?>.</span><div class="flex-grow-1"><span class="math-content"><?= e($q['body']) ?></span><?= !empty($q['image_file_id']) ? ' <i class="bi bi-image text-muted" title="بصورة"></i>' : '' ?> <span class="badge text-bg-secondary"><?= (float)$q['pts'] ?></span> <span class="badge text-bg-info"><?= e($kinds[$q['kind']]) ?></span></div>
  <?php if (!$locked): ?><button class="btn btn-sm btn-outline-danger" data-api="<?= url("api/v1/school/lms/quizzes/$id/questions/" . (int)$q['id']) ?>" data-method="DELETE" aria-label="إزالة"><i class="bi bi-x"></i></button><?php endif; ?></div><?php endforeach; ?>
  <?php if (!$locked && $bank): $used = array_column($z['questions'], 'id'); ?><form class="mt-3" method="post" action="<?= url("api/v1/school/lms/quizzes/$id/questions") ?>" data-ajax data-reload novalidate><?= csrf_field() ?><h4 class="h6">إضافة من البنك</h4><div style="max-height:220px;overflow:auto"><?php foreach ($bank as $q): if (in_array($q['id'], $used)) continue; ?><div class="form-check"><input class="form-check-input" type="checkbox" name="question_ids[]" value="<?= (int)$q['id'] ?>" id="bq<?= (int)$q['id'] ?>"><label class="form-check-label" for="bq<?= (int)$q['id'] ?>"><?= e(mb_substr($q['body'], 0, 70)) ?> <small class="text-muted">(<?= e($kinds[$q['kind']]) ?>)</small></label></div><?php endforeach; ?></div><button class="btn btn-primary btn-sm mt-2" type="submit">إضافة المحدَّد</button></form><?php endif; ?></div></div>
  <div class="col-lg-6"><div class="card-s"><h3 class="h6">المحاولات (<?= count($attempts) ?>)</h3><?php if (!$attempts): ?><div class="empty-state">لا توجد محاولات.</div><?php else: ?><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>الطالب</th><th>الحالة</th><th>الدرجة</th><th></th></tr></thead><tbody><?php foreach ($attempts as $a): ?><tr><td><?= e($a['full_name']) ?></td><td><span class="badge text-bg-<?= ['in_progress' => 'warning', 'submitted' => 'info', 'graded' => 'success'][$a['status']] ?>"><?= ['in_progress' => 'جارية', 'submitted' => 'بانتظار تصحيح ' . (int)$a['pending'], 'graded' => 'مُصحَّحة'][$a['status']] ?></span></td><td><?= $a['score'] === null ? '—' : (float)$a['score'] ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= url('school/lms/attempts/' . (int)$a['id']) ?>">عرض</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></div>
